 const existing=new Set(row.occurrences.map(item=>gmPlanForecastEventKey(item.plannedDate,precisionParse(item.hoursText,{scale:3,blank:'null'})))),added=model.events.filter(event=>!existing.has(gmPlanForecastEventKey(event.plannedDate,event.plannedHours))),placeholder=row.occurrences.find(item=>item.placeholder&&item.plannedDate===''&&item.hoursText==='');
 if(added.length){if(s.rows.reduce((count,item)=>count+item.occurrences.length,0)-(placeholder?1:0)+added.length>10000)throw Error('В графике получится больше 10 000 ТО. Сократите период или уточните интервал.');if((row.note.trim()+'\n\n'+model.provenance).length>10000)throw Error('Примечание вместе с основанием расчёта слишком длинное. Сократите примечание шаблона.');if(placeholder)row.occurrences=row.occurrences.filter(item=>item!==placeholder);for(const [index,event]of added.entries())row.occurrences.push({...gmPlanRawOccurrence({...event,id:index===0&&placeholder?placeholder.id:wfId('maintenance-row')}),forecastNote:model.provenance,forecastOrigin:{plannedDate:event.plannedDate,plannedHours:event.plannedHours}});}
 f.appliedSignature=gmPlanForecastSignature(s,row);f.previewSignature=gmPlanForecastPreviewSignature(s,row);f.message=added.length?'Добавлено плановых ТО: '+added.length+'. Существующие даты и фактические данные не изменены.':'Все рассчитанные даты и отметки уже есть. Повтор ничего не добавил.';row.openMonths=[...new Set([...(row.openMonths||[]),...model.events.map(event=>Number(event.plannedDate.slice(5,7)))])];f.open=true;
