async function generatorMaintenanceCommit(s){if(s.pending)return;let unlock;try{gmUiCurrent(s);if(!gmUiSupported('plans')||!gmUiWrite('generatorMaintenancePlans'))throw Error(gmUiUnavailable('plans'));const input=generatorMaintenanceInput(s),text=JSON.stringify(input);if(!s.review?.canApply||s.review.input!==text||!s.form.elements.confirm.checked)throw Error('Проверьте содержание и явно подтвердите выбранное действие');if(s.operationText!==text){s.operationText=text;s.operationId=wfId('generator-maintenance');}s.pending=true;unlock=gmUiLock(s);s.form.querySelector('[data-gm-status]').textContent='Ожидается подтверждение операции…';const result=await platformExecuteCommand({type:'GeneratorMaintenanceAction',version:1,input:{...input,reviewFingerprint:s.review.fingerprint}},{operationId:s.operationId});if(!result?.ok)throw Object.assign(Error(result?.message||result?.error||'Операция не подтверждена. Введённые значения остаются в форме.'),{unknown:!!result?.unknown});gmUiCurrent(s,false);const id=gmPlanAcknowledgedId(s,input,result);s.committed=true;generatorMaintenanceEdit(id);showToast(input.action==='approve'?'График утверждён':input.action==='revise'?'Создана отдельная новая редакция':'Черновик сохранён');}catch(error){gmUiError(s,error);}finally{s.pending=false;if(unlock)unlock();s.form.querySelector('[data-gm-status]').textContent='';s.form.querySelector('[data-gm-save]').disabled=!s.review?.canApply||!s.form.elements.confirm.checked;}}
function generatorMaintenanceActionOpen(id,action){try{if(!['approve','revise'].includes(action))throw Error('Неизвестное действие графика');if(!gmUiSupported('plans')||!gmUiWrite('generatorMaintenancePlans'))throw Error(gmUiUnavailable('plans'));const plan=gmPlanFind(id),s=gmUiContextState('planAction',GM_UI_READS);s.id=id;s.action=action;s.plan=gmUiClone(plan);const form=gmUiModal(s,action==='approve'?'Утверждение графика ТО ДЭС':'Новая редакция графика ТО ДЭС','<form id="generatorMaintenanceActionForm" class="gm-ui-form">'+gmPlanSnapshotHtml(plan)+(action==='approve'?'<div class="gm-ui-grid"><label>Фактическая дата утверждения<input type="date" name="date" required></label><label>Приказ / решение комиссии<input name="document" required></label></div>':'<p>Утверждённая редакция остаётся неизменной. Будет создан отдельный черновик новой редакции.</p>')+'<label>Основание действия<textarea name="reason" required></textarea></label>'+gmUiFooter(action==='approve'?'Утвердить график':'Создать новую редакцию')+'</form>');gmUiBind(s,generatorMaintenancePreview,generatorMaintenanceCommit);form.elements.reason.focus();}catch(error){showToast(error.message);}}
function generatorMaintenanceReadonly(id){try{const plan=gmPlanFind(id),database=data,stamp=gmUiStamp(),source=gmUiSource(['generatorMaintenancePlans']);if(plan.status!=='approved'||!plan.snapshot)throw Error('Утверждённый снимок графика отсутствует');if(generatorMaintenanceApi().snapshotDigest(plan.snapshot)!==plan.fingerprint||plan.id!==plan.snapshot.planId||plan.rootId!==plan.snapshot.rootId||plan.revision!==plan.snapshot.revision||plan.previousId!==plan.snapshot.previousId||PlatformKernel.stableSerialize(plan.approval)!==PlatformKernel.stableSerialize(plan.snapshot.approval))throw Error('Контрольная сумма утверждённого графика не совпадает');wfShowDialog('Утверждённый график ТО · редакция '+plan.snapshot.revision,'<div class="gm-ui-form" id="generatorMaintenanceReadonly">'+gmPlanSnapshotHtml(plan)+'<p>Утверждённая редакция доступна только для чтения. Нажмите «Новая редакция», чтобы подготовить отдельный черновик.</p><div class="gm-ui-actions"><button type="button" class="btn btn-ghost" data-gm-print>График ТО</button><button type="button" class="btn btn-ghost" data-gm-spares>Перечень ЗИП</button><button type="button" class="btn btn-primary" data-gm-revise'+(gmUiSupported('plans')&&gmUiWrite('generatorMaintenancePlans')?'':' disabled')+'>Новая редакция</button></div></div>');const modal=document.getElementById('wfModal');modal.querySelector('.wf-modal').classList.add('gm-ui-modal');const current=()=>{if(database!==data||stamp!==gmUiStamp()||source!==gmUiSource(['generatorMaintenancePlans'])||!modal.isConnected||!modal.classList.contains('open'))throw Error('Документ или сеанс изменились. Откройте график заново');};modal.querySelector('[data-gm-print]').onclick=()=>{try{current();generatorMaintenancePrint(id);}catch(error){showToast(error.message);}};modal.querySelector('[data-gm-spares]').onclick=()=>{try{current();generatorMaintenancePrint(id,{document:'spares'});}catch(error){showToast(error.message);}};modal.querySelector('[data-gm-revise]').onclick=()=>{try{current();generatorMaintenanceActionOpen(id,'revise');}catch(error){showToast(error.message);}};}catch(error){showToast(error.message);}}
